package com.forestrytracker;

import java.time.LocalDate;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LifetimeStatsTest
{
	@Test
	public void perDayFiguresAccumulateIndependently()
	{
		LifetimeStats stats = new LifetimeStats();
		stats.addBark(5, ForestryEvent.RISING_ROOTS, "2026-09-01");
		stats.addBark(3, ForestryEvent.RISING_ROOTS, "2026-09-02");
		stats.addEvent(ForestryEvent.RISING_ROOTS, "2026-09-01");
		stats.addEvent(ForestryEvent.BEE_HIVE, "2026-09-02");
		stats.addLeaves(LeafType.OAK, 4, "2026-09-01");
		stats.addLog("Oak logs", "2026-09-02");
		stats.addLog("Oak logs", "2026-09-02");
		stats.addXp(100L, "2026-09-01");
		stats.addXp(200L, "2026-09-02");

		assertEquals(8, stats.getBark());
		assertEquals(2, stats.getEventsSeen());
		assertEquals(2, stats.getLogs());
		assertEquals(300L, stats.getXp());

		Map<String, DayStats> days = stats.getDays();
		assertEquals(2, days.size());

		DayStats day1 = days.get("2026-09-01");
		assertEquals(5, day1.bark);
		assertEquals(1, day1.events);
		assertEquals(4, day1.leaves);
		assertEquals(0, day1.logs);
		assertEquals(100L, day1.xp);

		DayStats day2 = days.get("2026-09-02");
		assertEquals(3, day2.bark);
		assertEquals(1, day2.events);
		assertEquals(2, day2.logs);
		assertEquals(200L, day2.xp);
	}

	@Test
	public void zeroAndNegativeAmountsAreIgnoredPerDay()
	{
		LifetimeStats stats = new LifetimeStats();
		stats.addLeaves(LeafType.YEW, 0, "2026-09-01");
		stats.addLeaves(LeafType.YEW, -3, "2026-09-01");
		stats.addXp(0L, "2026-09-01");
		stats.addXp(-5L, "2026-09-01");

		assertEquals(0, stats.getTotalLeaves());
		assertEquals(0L, stats.getXp());
		assertTrue(stats.getDays().isEmpty());
	}

	@Test
	public void daysAreKeptOldestFirst()
	{
		LifetimeStats stats = new LifetimeStats();
		stats.addLog("Logs", "2026-09-03");
		stats.addLog("Logs", "2026-09-01");
		stats.addLog("Logs", "2026-09-02");

		assertEquals("[2026-09-01, 2026-09-02, 2026-09-03]", stats.getDays().keySet().toString());
	}

	@Test
	public void oldestDaysAreEvictedBeyondMaxDays()
	{
		LifetimeStats stats = new LifetimeStats();
		LocalDate start = LocalDate.parse("2026-01-01");
		int totalDays = LifetimeStats.MAX_DAYS + 5;
		for (int i = 0; i < totalDays; i++)
		{
			stats.addLog("Logs", start.plusDays(i).toString());
		}

		Map<String, DayStats> days = stats.getDays();
		assertEquals(LifetimeStats.MAX_DAYS, days.size());

		// The 5 oldest days were evicted as the cap was exceeded.
		for (int i = 0; i < 5; i++)
		{
			assertFalse(days.containsKey(start.plusDays(i).toString()));
		}
		assertTrue(days.containsKey(start.plusDays(5).toString()));
		assertTrue(days.containsKey(start.plusDays(totalDays - 1).toString()));

		// Lifetime totals are unaffected by day-bucket eviction.
		assertEquals(totalDays, stats.getLogs());
	}
}

package com.forestrytracker;

import java.time.Instant;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.ChatMessageType;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for the chat-handling and entity-spawn glue in {@link ForestryTrackerPlugin}: {@link
 * ForestryTrackerPlugin#handleChatMessage} (the body of {@code onChatMessage}) and {@link
 * ForestryTrackerPlugin#startOrResumeEvent} (the start-vs-resume decision in {@code
 * entitySpawned}) were extracted as package-private, RuneLite-{@code Client}-free helpers
 * specifically so this glue can be exercised directly, the way {@link ForestrySessionTest} and
 * {@link ChatParserTest} already exercise the pure model and pure parser layers.
 *
 * <p>{@link ForestryTrackerPluginTest} (despite its name) is a manual dev-mode launcher used by the
 * {@code run}/{@code shadowJar} Gradle tasks, not a JUnit test; this class is the actual coverage
 * for the plugin-level wiring.
 */
public class ForestryTrackerPluginChatTest
{
	private static final String DAY = "2026-09-17";

	private Instant now;
	private ForestrySession session;
	private LifetimeStats lifetime;
	private Map<ForestryEvent, Set<Object>> liveEntities;

	@Before
	public void setUp()
	{
		now = Instant.parse("2026-09-17T08:18:17Z");
		session = new ForestrySession(() -> now);
		lifetime = new LifetimeStats();
		liveEntities = new EnumMap<>(ForestryEvent.class);
		for (ForestryEvent event : ForestryEvent.values())
		{
			liveEntities.put(event, new HashSet<>());
		}
	}

	private final ChatState chatState = new ChatState();

	private boolean handle(ChatMessageType type, String message)
	{
		return ForestryTrackerPlugin.handleChatMessage(type, message, () -> session, liveEntities, lifetime, DAY, chatState);
	}

	// --- Leprechaun's Luck (real captured messages) --------------------------------------------------------------

	@Test
	public void leprechaunIsNotEndedByChoppingAndLuckBarkAccumulates()
	{
		Object leprechaun = new Object();
		liveEntities.get(ForestryEvent.LEPRECHAUN).add(leprechaun);
		session.startEvent(ForestryEvent.LEPRECHAUN);

		assertFalse(handle(ChatMessageType.GAMEMESSAGE, "You feel more in touch with the trees after standing in the rainbow."));
		assertFalse(handle(ChatMessageType.SPAM, "You use your leprechaun's luck to gather some Anima-infused bark."));
		assertTrue(handle(ChatMessageType.SPAM, "You've been awarded @mes_hl_blu@22 Anima-infused bark</col>."));
		assertTrue(handle(ChatMessageType.SPAM, "You get some willow logs."));
		assertFalse(handle(ChatMessageType.SPAM, "You use your leprechaun's luck to gather some Anima-infused bark."));
		assertTrue(handle(ChatMessageType.SPAM, "You've been awarded @mes_hl_blu@23 Anima-infused bark</col>."));

		// Still the same, open event: chopping is how leprechaun bark is earned.
		assertEquals(ForestryEvent.LEPRECHAUN, session.getCurrentEvent());
		assertEquals(45, session.getCurrentEventBark());
		assertEquals(1, session.getEventsSeen());
		assertTrue(session.getHistory().isEmpty());
		assertEquals(45, lifetime.getBarkForEvent(ForestryEvent.LEPRECHAUN));
	}

	@Test
	public void luckBarkAfterLeprechaunLeftGoesToItsRecordAndClosesAgain()
	{
		session.startEvent(ForestryEvent.LEPRECHAUN);
		session.addBark(22);
		session.endEvent(); // leprechaun despawned; no live entities remain
		now = now.plusSeconds(60); // well past the 10-second grace

		assertFalse(handle(ChatMessageType.GAMEMESSAGE, "You use the last of your leprechaun's luck to gather some Anima-infused bark."));
		assertTrue(handle(ChatMessageType.SPAM, "You've been awarded @mes_hl_blu@23 Anima-infused bark</col>."));

		assertNull(session.getCurrentEvent());
		assertEquals(1, session.getHistory().size());
		assertEquals(ForestryEvent.LEPRECHAUN, session.getHistory().get(0).getEvent());
		assertEquals(45, session.getHistory().get(0).getBark());
		assertEquals(45, session.getLastEventBark());
		assertEquals(1, session.getEventsSeen());
	}

	@Test
	public void luckFlagIsConsumedByTheNextAwardOnly()
	{
		session.startEvent(ForestryEvent.LEPRECHAUN);
		session.endEvent();
		now = now.plusSeconds(60);

		assertFalse(handle(ChatMessageType.SPAM, "You use your leprechaun's luck to gather some Anima-infused bark."));
		assertTrue(handle(ChatMessageType.SPAM, "You've been awarded @mes_hl_blu@10 Anima-infused bark</col>."));
		// A later award (past the grace window) with no luck line and no live event is standalone.
		now = now.plusSeconds(60);
		assertTrue(handle(ChatMessageType.SPAM, "You've been awarded @mes_hl_blu@5 Anima-infused bark</col>."));

		assertEquals(2, session.getHistory().size());
		assertNull(session.getHistory().get(0).getEvent());
		assertEquals(5, session.getHistory().get(0).getBark());
		assertEquals(ForestryEvent.LEPRECHAUN, session.getHistory().get(1).getEvent());
		assertEquals(10, session.getHistory().get(1).getBark());
	}

	// --- real captured messages, end-to-end through the plugin glue (not just ChatParser in isolation) ----------

	@Test
	public void spamBarkAwardsAccumulateIntoSessionAndLifetime()
	{
		session.startEvent(ForestryEvent.RISING_ROOTS);

		assertTrue(handle(ChatMessageType.SPAM, "You've been awarded @mes_hl_blu@11 Anima-infused bark</col>."));
		assertTrue(handle(ChatMessageType.SPAM, "You've been awarded @mes_hl_blu@21 Anima-infused bark</col>."));
		assertTrue(handle(ChatMessageType.GAMEMESSAGE, "You've been awarded @mes_hl_blu@143 Anima-infused bark</col>."));

		assertEquals(175, session.getTotalBark());
		assertEquals(175, session.getBarkForEvent(ForestryEvent.RISING_ROOTS));
		assertEquals(175, lifetime.getBark());
		assertEquals(175, lifetime.getBarkForEvent(ForestryEvent.RISING_ROOTS));
	}

	@Test
	public void legacyColTagBarkFormatStillWorks()
	{
		assertTrue(handle(ChatMessageType.GAMEMESSAGE, "You've been awarded <col=0000ff>11 Anima-infused bark</col>."));

		assertEquals(11, session.getTotalBark());
	}

	@Test
	public void spamWillowLeafPickupIsCounted()
	{
		assertTrue(handle(ChatMessageType.SPAM,
			"Some willow leaves fall to the ground and you place them into your Forestry kit."));

		assertEquals(1, session.getLeaves(LeafType.WILLOW));
		assertEquals(1, lifetime.getLeaves(LeafType.WILLOW));
	}

	@Test
	public void spamWillowLogMessageIsCountedAsALog()
	{
		assertTrue(handle(ChatMessageType.SPAM, "You get some willow logs."));

		assertEquals(1, session.getLogsCut());
		assertEquals(1, lifetime.getLogs());
	}

	@Test
	public void ritualCompletionGameMessageIsIgnored()
	{
		assertFalse(handle(ChatMessageType.GAMEMESSAGE,
			"@mes_hl_blu@Well done, you completed 8 steps of the ritual! The Dryad has left you a gift...</col>"));

		assertEquals(0, session.getTotalBark());
		assertEquals(0, session.getTotalLeaves());
		assertEquals(0, session.getLogsCut());
	}

	@Test
	public void nonForestryChatTypeIsIgnoredEvenForABarkShapedMessage()
	{
		assertFalse(handle(ChatMessageType.PUBLICCHAT, "You've been awarded 11 Anima-infused bark."));

		assertEquals(0, session.getTotalBark());
	}

	@Test
	public void mesboxLeafMessageIsIgnored()
	{
		// Leaf/log messages are only ever SPAM/GAMEMESSAGE in game, unlike bark awards which can also
		// arrive as MESBOX; onChatMessage's second type filter (mirrored in handleChatMessage) reflects that.
		assertFalse(handle(ChatMessageType.MESBOX,
			"Some willow leaves fall to the ground and you place them into your Forestry kit."));

		assertEquals(0, session.getTotalLeaves());
	}

	// --- bark reopens an event ended early (rule 1 / resumeLastEvent), per handleChatMessage --------------------

	@Test
	public void barkAfterLogCutEndedEventReopensItInsteadOfStartingUnknownEvent()
	{
		session.startEvent(ForestryEvent.RISING_ROOTS);
		session.addBark(5);
		// The root object is still alive in the world even though the plugin ended participation below.
		liveEntities.get(ForestryEvent.RISING_ROOTS).add(new Object());

		session.endEvent(); // what onChatMessage's log-cut rule already did
		assertNull(session.getCurrentEvent());
		assertEquals(1, session.getHistory().size());

		assertTrue(handle(ChatMessageType.SPAM, "You've been awarded @mes_hl_blu@11 Anima-infused bark</col>."));

		assertEquals(ForestryEvent.RISING_ROOTS, session.getCurrentEvent());
		assertEquals(16, session.getTotalBark());
		assertEquals(1, session.getEventsSeen());
		assertEquals(1, session.getEventCount(ForestryEvent.RISING_ROOTS));
		assertTrue("bark should merge back into the reopened event, not sit in history", session.getHistory().isEmpty());
	}

	@Test
	public void barkWithNoLiveEntitiesForLastEventFallsBackToGraceWindowAttributionInstead()
	{
		session.startEvent(ForestryEvent.RISING_ROOTS);
		session.addBark(5);
		session.endEvent();
		// liveEntities never populated for RISING_ROOTS (it fully despawned) -> nothing to reopen.

		assertTrue(handle(ChatMessageType.SPAM, "You've been awarded @mes_hl_blu@11 Anima-infused bark</col>."));

		assertNull(session.getCurrentEvent());
		assertEquals(1, session.getHistory().size());
		assertEquals(16, session.getHistory().get(0).getBark());
	}

	// --- log-cut ends participation, but only once bark has been awarded (rule 1) -------------------------------

	@Test
	public void logCutEndsEventParticipationOnceBarkAwarded()
	{
		session.startEvent(ForestryEvent.RISING_ROOTS);
		session.addBark(5);

		assertTrue(handle(ChatMessageType.SPAM, "You get some willow logs."));

		assertNull(session.getCurrentEvent());
		assertEquals(1, session.getHistory().size());
		assertEquals(5, session.getHistory().get(0).getBark());
		assertEquals(1, session.getLogsCut());
	}

	@Test
	public void logCutDoesNotEndEventWithNoBarkYet()
	{
		session.startEvent(ForestryEvent.LEPRECHAUN);

		assertTrue(handle(ChatMessageType.SPAM, "You get some willow logs."));

		assertEquals(ForestryEvent.LEPRECHAUN, session.getCurrentEvent());
		assertTrue(session.getHistory().isEmpty());
		assertEquals(1, session.getLogsCut());
	}

	@Test
	public void logCutWithNoCurrentEventJustCountsTheLog()
	{
		assertTrue(handle(ChatMessageType.SPAM, "You get some logs."));

		assertNull(session.getCurrentEvent());
		assertEquals(1, session.getLogsCut());
		assertEquals(1, lifetime.getLogs());
	}

	// --- entitySpawned's start-vs-resume decision (startOrResumeEvent) -------------------------------------------

	@Test
	public void newGlowingRootAfterEarlyEndResumesInsteadOfStartingASecondEvent()
	{
		session.startEvent(ForestryEvent.RISING_ROOTS);
		session.addBark(5);
		session.endEvent();
		assertEquals(1, session.getEventsSeen());
		assertEquals(1, session.getHistory().size());

		boolean startedNew = ForestryTrackerPlugin.startOrResumeEvent(session, ForestryEvent.RISING_ROOTS);

		assertFalse(startedNew);
		assertEquals(ForestryEvent.RISING_ROOTS, session.getCurrentEvent());
		assertEquals(1, session.getEventsSeen());
		assertEquals(5, session.getCurrentEventBark());
		assertTrue(session.getHistory().isEmpty());
	}

	@Test
	public void spawnWithNoPriorHistoryStartsANewEvent()
	{
		boolean startedNew = ForestryTrackerPlugin.startOrResumeEvent(session, ForestryEvent.RISING_ROOTS);

		assertTrue(startedNew);
		assertEquals(1, session.getEventsSeen());
		assertEquals(ForestryEvent.RISING_ROOTS, session.getCurrentEvent());
	}

	@Test
	public void spawnOfADifferentEventThanTheLastHistoryRecordStartsANewEvent()
	{
		session.startEvent(ForestryEvent.RISING_ROOTS);
		session.endEvent();

		boolean startedNew = ForestryTrackerPlugin.startOrResumeEvent(session, ForestryEvent.LEPRECHAUN);

		assertTrue(startedNew);
		assertEquals(2, session.getEventsSeen());
		assertEquals(ForestryEvent.LEPRECHAUN, session.getCurrentEvent());
		assertEquals(1, session.getHistory().size());
		assertEquals(ForestryEvent.RISING_ROOTS, session.getHistory().get(0).getEvent());
	}

	@Test
	public void spawnWhileAnotherEventIsCurrentEndsItAndStartsTheNewOne()
	{
		session.startEvent(ForestryEvent.LEPRECHAUN);

		boolean startedNew = ForestryTrackerPlugin.startOrResumeEvent(session, ForestryEvent.RISING_ROOTS);

		assertTrue(startedNew);
		assertEquals(2, session.getEventsSeen());
		assertEquals(ForestryEvent.RISING_ROOTS, session.getCurrentEvent());
		assertEquals(1, session.getHistory().size());
		assertEquals(ForestryEvent.LEPRECHAUN, session.getHistory().get(0).getEvent());
	}
}

package com.forestrytracker;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class BarChartTest
{
	@Test
	public void wholeNumbersBelowAThousandAreExact()
	{
		assertEquals("0", BarChart.format(0));
		assertEquals("42", BarChart.format(42));
		assertEquals("999", BarChart.format(999));
	}

	@Test
	public void thousandsRangeKeepsOneDecimalOfPrecision()
	{
		// 12,400 must read as "12.4k", not be truncated to whole thousands like "12k".
		assertEquals("12.4k", BarChart.format(12_400));
		assertEquals("1k", BarChart.format(1_000));
		assertEquals("999.9k", BarChart.format(999_900));
	}

	@Test
	public void millionsRangeDropsToOneDecimal()
	{
		assertEquals("1m", BarChart.format(1_000_000));
		assertEquals("2.5m", BarChart.format(2_500_000));
	}
}

package com.forestrytracker;

import java.time.Duration;
import java.time.Instant;
import java.util.List;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ForestrySessionTest
{
	private Instant now;
	private ForestrySession session;

	@Before
	public void setUp()
	{
		now = Instant.parse("2026-09-16T12:00:00Z");
		session = new ForestrySession(() -> now);
	}

	private void advance(Duration d)
	{
		now = now.plus(d);
	}

	@Test
	public void barkDuringEventAccumulatesIntoThatEvent()
	{
		session.startEvent(ForestryEvent.FLOWERING_TREE);
		session.addBark(2);
		session.addBark(1);
		session.addBark(2);

		assertEquals(5, session.getTotalBark());
		assertEquals(5, session.getLastEventBark());
		assertEquals(ForestryEvent.FLOWERING_TREE, session.getCurrentEvent());
		assertEquals(5, session.getBarkForEvent(ForestryEvent.FLOWERING_TREE));
		assertEquals(1, session.getEventCount(ForestryEvent.FLOWERING_TREE));

		session.endEvent();
		assertNull(session.getCurrentEvent());
		assertEquals(5, session.getLastEventBark());
		assertEquals(ForestryEvent.FLOWERING_TREE, session.getLastEvent());
		assertEquals(1, session.getHistory().size());
		assertEquals(5, session.getHistory().get(0).getBark());
	}

	@Test
	public void barkShortlyAfterEventEndsIsAttributedToIt()
	{
		session.startEvent(ForestryEvent.STRUGGLING_SAPLING);
		advance(Duration.ofSeconds(90));
		session.endEvent();
		advance(Duration.ofSeconds(2));
		session.addBark(12);

		assertEquals(12, session.getLastEventBark());
		assertEquals(ForestryEvent.STRUGGLING_SAPLING, session.getLastEvent());
		assertEquals(1, session.getHistory().size());
		assertEquals(12, session.getHistory().get(0).getBark());
		assertEquals(12, session.getBarkForEvent(ForestryEvent.STRUGGLING_SAPLING));
	}

	@Test
	public void barkWithNoEventIsRecordedStandalone()
	{
		session.startEvent(ForestryEvent.RISING_ROOTS);
		session.addBark(4);
		session.endEvent();
		advance(ForestrySession.BARK_ATTRIBUTION_GRACE.plusSeconds(1));
		session.addBark(7);

		assertEquals(11, session.getTotalBark());
		assertEquals(7, session.getLastEventBark());
		assertNull(session.getLastEvent());
		assertEquals(2, session.getHistory().size());
		assertNull(session.getHistory().get(0).getEvent());
		assertEquals(7, session.getHistory().get(0).getBark());
		assertEquals("Unknown event", session.getHistory().get(0).getEventName());
	}

	@Test
	public void startingAnEventEndsThePreviousOne()
	{
		session.startEvent(ForestryEvent.BEE_HIVE);
		session.addBark(10);
		session.startEvent(ForestryEvent.POACHERS);

		assertEquals(ForestryEvent.POACHERS, session.getCurrentEvent());
		assertEquals(0, session.getCurrentEventBark());
		assertEquals(2, session.getEventsSeen());
		assertEquals(1, session.getHistory().size());
		assertEquals(ForestryEvent.BEE_HIVE, session.getHistory().get(0).getEvent());
		assertEquals(10, session.getHistory().get(0).getBark());
	}

	@Test
	public void barkPerHourUsesSessionElapsedTime()
	{
		assertEquals(0, session.getBarkPerHour());
		advance(Duration.ofMinutes(30));
		session.addBark(50);
		assertEquals(100, session.getBarkPerHour());
		advance(Duration.ofMinutes(30));
		assertEquals(50, session.getBarkPerHour());
	}

	@Test
	public void timeSinceLastEventPrefersEventStartOverBark()
	{
		assertNull(session.getTimeSinceLastEvent());

		session.addBark(3);
		advance(Duration.ofSeconds(20));
		assertEquals(Duration.ofSeconds(20), session.getTimeSinceLastEvent());

		session.startEvent(ForestryEvent.LEPRECHAUN);
		advance(Duration.ofSeconds(5));
		session.addBark(1);
		advance(Duration.ofSeconds(5));
		assertEquals(Duration.ofSeconds(10), session.getTimeSinceLastEvent());
	}

	@Test
	public void leavesAreSummedPerType()
	{
		session.addLeaves(LeafType.OAK, 3);
		session.addLeaves(LeafType.OAK, 2);
		session.addLeaves(LeafType.MAGIC, 1);
		session.addLeaves(LeafType.YEW, 0);
		session.addLeaves(LeafType.YEW, -4);

		assertEquals(5, session.getLeaves(LeafType.OAK));
		assertEquals(1, session.getLeaves(LeafType.MAGIC));
		assertEquals(0, session.getLeaves(LeafType.YEW));
		assertEquals(6, session.getTotalLeaves());
	}

	@Test
	public void activityTracking()
	{
		assertTrue(session.isActive());
		session.setActive(false);
		assertFalse(session.isActive());
		advance(Duration.ofMinutes(3));
		session.addBark(1);
		assertTrue(session.isActive());
		assertEquals(Duration.ZERO, session.getTimeSinceActivity());
	}

	@Test
	public void historyIsCapped()
	{
		for (int i = 0; i < 150; i++)
		{
			session.startEvent(ForestryEvent.RISING_ROOTS);
			session.endEvent();
		}
		assertEquals(100, session.getHistory().size());
		assertEquals(150, session.getEventsSeen());
	}

	@Test
	public void logsAreTrackedPerTypeAndTotal()
	{
		session.addLog("Oak logs");
		session.addLog("Oak logs");
		session.addLog("Logs");

		assertEquals(3, session.getLogsCut());
		assertEquals(Integer.valueOf(2), session.getLogsByType().get("Oak logs"));
		assertEquals(Integer.valueOf(1), session.getLogsByType().get("Logs"));

		advance(Duration.ofMinutes(30));
		assertEquals(6, session.getLogsPerHour());
	}

	@Test
	public void xpIsTrackedAndPerHourIsComputed()
	{
		advance(Duration.ofMinutes(30));
		session.addXp(500);
		assertEquals(500, session.getXpGained());
		assertEquals(1000, session.getXpPerHour());

		// Non-positive deltas (e.g. a stat recalculation) are ignored.
		session.addXp(0);
		session.addXp(-10);
		assertEquals(500, session.getXpGained());
	}

	@Test
	public void timelineBucketsActivityInFiveMinuteSlices()
	{
		session.addLog("Logs");
		advance(Duration.ofMinutes(5));
		session.addBark(3);
		advance(Duration.ofMinutes(5));
		session.addLeaves(LeafType.OAK, 2);
		advance(Duration.ofMinutes(1));
		session.addXp(20);

		List<TimeBucket> timeline = session.getTimeline();
		assertEquals(3, timeline.size());
		assertEquals(1, timeline.get(0).logs);
		assertEquals(0, timeline.get(1).logs);
		assertEquals(3, timeline.get(1).bark);
		assertEquals(2, timeline.get(2).leaves);
		assertEquals(20, timeline.get(2).xp);
		assertEquals(session.getStart().toEpochMilli(), timeline.get(0).start);
		assertEquals(session.getStart().toEpochMilli() + ForestrySession.BUCKET.toMillis(), timeline.get(1).start);
		assertEquals(session.getStart().toEpochMilli() + 2 * ForestrySession.BUCKET.toMillis(), timeline.get(2).start);
	}

	@Test
	public void durationFreezesAtLastActivityWhenInactive()
	{
		advance(Duration.ofMinutes(10));
		session.addBark(1);
		session.setActive(false);
		advance(Duration.ofMinutes(50));

		assertEquals(Duration.ofMinutes(10), session.getDuration());
	}

	@Test
	public void averageEventGapIsMeanTimeBetweenEventStarts()
	{
		assertNull(session.getAverageEventGap());

		session.startEvent(ForestryEvent.RISING_ROOTS);
		assertNull(session.getAverageEventGap());
		advance(Duration.ofMinutes(4));
		session.endEvent();

		advance(Duration.ofMinutes(6));
		session.startEvent(ForestryEvent.BEE_HIVE);
		assertEquals(Duration.ofMinutes(10), session.getAverageEventGap());

		advance(Duration.ofMinutes(5));
		session.endEvent();
		advance(Duration.ofMinutes(5));
		session.startEvent(ForestryEvent.POACHERS);
		assertEquals(Duration.ofMinutes(10), session.getAverageEventGap());
	}

	@Test
	public void bestEventIsTheHighestBarkCompletedEvent()
	{
		assertNull(session.getBestEvent());

		session.startEvent(ForestryEvent.RISING_ROOTS);
		session.addBark(5);
		session.endEvent();
		session.startEvent(ForestryEvent.BEE_HIVE);
		session.addBark(20);
		session.endEvent();
		session.startEvent(ForestryEvent.POACHERS);
		session.addBark(9);
		session.endEvent();

		EventRecord best = session.getBestEvent();
		assertNotNull(best);
		assertEquals(ForestryEvent.BEE_HIVE, best.getEvent());
		assertEquals(20, best.getBark());
	}

	@Test
	public void reactivatingAfterTimeoutExcludesTheIdleGapFromDuration()
	{
		advance(Duration.ofMinutes(30));
		session.addLog("Oak logs");
		session.setActive(false);
		advance(Duration.ofHours(3));

		// Resuming (e.g. resetOnTimeout=false) must not let the 3-hour idle gap flood back in.
		session.touch();
		assertTrue(session.isActive());
		assertEquals(Duration.ofMinutes(30), session.getDuration());

		advance(Duration.ofMinutes(10));
		session.addLog("Oak logs");
		assertEquals(Duration.ofMinutes(40), session.getDuration());
		assertEquals(2, session.getLogsCut());
		// 2 logs over 40 real minutes -> 3/hr, not deflated by the idle gap.
		assertEquals(3, session.getLogsPerHour());
	}

	@Test
	public void repeatedTimeoutsAccumulateExcludedIdleTime()
	{
		session.addLog("Oak logs");
		session.setActive(false);
		advance(Duration.ofHours(1));
		session.touch();

		session.addLog("Oak logs");
		session.setActive(false);
		advance(Duration.ofHours(2));
		session.touch();

		assertEquals(Duration.ZERO, session.getDuration());
	}

	@Test
	public void timelineIsCappedWhenActivityResumesAfterAVeryLongGap()
	{
		session.addLog("Oak logs");
		// Simulate a stale session (e.g. restored after several real days) suddenly active again.
		advance(Duration.ofDays(5));
		session.addLog("Oak logs");

		List<TimeBucket> timeline = session.getTimeline();
		assertTrue("timeline must be bounded, was " + timeline.size(), timeline.size() <= 288);
		// The most recent slice (containing the log just cut) must still be present and correct.
		TimeBucket last = timeline.get(timeline.size() - 1);
		assertEquals(1, last.logs);
	}

	@Test
	public void resumeLastEventReattachesLaterBarkWithoutDoubleCounting()
	{
		session.startEvent(ForestryEvent.RISING_ROOTS);
		session.addBark(11);
		session.endEvent();

		assertTrue(session.resumeLastEvent());
		assertEquals(ForestryEvent.RISING_ROOTS, session.getCurrentEvent());
		assertEquals(11, session.getCurrentEventBark());
		assertTrue(session.getHistory().isEmpty());

		// Bark after a resume must go straight to the current event, not the 10s grace path.
		session.addBark(10);
		assertEquals(21, session.getCurrentEventBark());
		assertTrue("grace path must not have created a history record", session.getHistory().isEmpty());

		session.endEvent();

		assertEquals(1, session.getHistory().size());
		assertEquals(21, session.getHistory().get(0).getBark());
		assertEquals(ForestryEvent.RISING_ROOTS, session.getHistory().get(0).getEvent());
		assertEquals(1, session.getEventsSeen());
		assertEquals(1, session.getEventCount(ForestryEvent.RISING_ROOTS));
		assertEquals(21, session.getBarkForEvent(ForestryEvent.RISING_ROOTS));
		assertEquals(21, session.getLastEventBark());
	}

	@Test
	public void resumeLastEventReturnsFalseWithNoResumableRecord()
	{
		assertFalse(session.resumeLastEvent());

		// A standalone "Unknown event" bark record is not resumable.
		session.addBark(4);
		assertFalse(session.resumeLastEvent());
		assertNull(session.getCurrentEvent());
		assertEquals(1, session.getHistory().size());

		// Not resumable while an event is already current.
		session.startEvent(ForestryEvent.BEE_HIVE);
		assertFalse(session.resumeLastEvent());
	}

	@Test
	public void isLastRecordIdentifiesTheMostRecentHistoryEntry()
	{
		assertFalse(session.isLastRecord(ForestryEvent.RISING_ROOTS));

		session.startEvent(ForestryEvent.RISING_ROOTS);
		session.endEvent();
		assertTrue(session.isLastRecord(ForestryEvent.RISING_ROOTS));
		assertFalse(session.isLastRecord(ForestryEvent.BEE_HIVE));

		session.startEvent(ForestryEvent.BEE_HIVE);
		session.endEvent();
		assertTrue(session.isLastRecord(ForestryEvent.BEE_HIVE));
		assertFalse(session.isLastRecord(ForestryEvent.RISING_ROOTS));
	}

	@Test
	public void eventsPerHourComputesRatePerHourWithOneDecimal()
	{
		assertEquals(0.0, session.getEventsPerHour(), 0.0001);

		session.startEvent(ForestryEvent.RISING_ROOTS);
		session.endEvent();
		session.startEvent(ForestryEvent.BEE_HIVE);
		session.endEvent();
		session.startEvent(ForestryEvent.POACHERS);
		session.endEvent();

		// 3 events within 20 minutes -> 9.0 per hour.
		advance(Duration.ofMinutes(20));
		assertEquals(9.0, session.getEventsPerHour(), 0.0001);
	}
}

package com.forestrytracker;

import com.google.gson.Gson;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SessionStateTest
{
	private static final Gson GSON = new Gson();
	private static final String DAY = "2026-09-17";

	@Test
	public void sessionRoundTripsThroughJson()
	{
		Instant[] now = {Instant.parse("2026-09-16T12:00:00Z")};
		ForestrySession original = new ForestrySession(() -> now[0]);
		original.startEvent(ForestryEvent.RISING_ROOTS);
		original.addBark(5);
		now[0] = now[0].plus(Duration.ofMinutes(1));
		original.endEvent();
		original.addLeaves(LeafType.OAK, 4);
		original.addLeaves(LeafType.MAGIC, 1);
		original.startEvent(ForestryEvent.BEE_HIVE);
		original.addBark(7);
		original.setActive(false);

		String json = GSON.toJson(original.toState());
		SessionState state = GSON.fromJson(json, SessionState.class);
		ForestrySession restored = new ForestrySession(state, () -> now[0]);

		assertEquals(original.getStart(), restored.getStart());
		assertEquals(original.getLastActivity(), restored.getLastActivity());
		assertFalse(restored.isActive());
		assertEquals(12, restored.getTotalBark());
		assertEquals(7, restored.getLastEventBark());
		assertEquals(ForestryEvent.BEE_HIVE, restored.getLastEvent());
		assertEquals(2, restored.getEventsSeen());
		assertEquals(1, restored.getEventCount(ForestryEvent.RISING_ROOTS));
		assertEquals(1, restored.getEventCount(ForestryEvent.BEE_HIVE));
		assertEquals(5, restored.getBarkForEvent(ForestryEvent.RISING_ROOTS));
		assertEquals(7, restored.getBarkForEvent(ForestryEvent.BEE_HIVE));
		assertEquals(4, restored.getLeaves(LeafType.OAK));
		assertEquals(5, restored.getTotalLeaves());

		// The in-progress bee hive event is persisted as a finished history entry.
		assertNull(restored.getCurrentEvent());
		assertEquals(2, restored.getHistory().size());
		assertEquals(ForestryEvent.BEE_HIVE, restored.getHistory().get(0).getEvent());
		assertEquals(7, restored.getHistory().get(0).getBark());
		assertEquals(ForestryEvent.RISING_ROOTS, restored.getHistory().get(1).getEvent());
	}

	@Test
	public void sessionRoundTripCoversLogsXpAndTimeline()
	{
		Instant[] now = {Instant.parse("2026-09-16T12:00:00Z")};
		ForestrySession original = new ForestrySession(() -> now[0]);
		original.addLog("Oak logs");
		original.addLog("Oak logs");
		original.addLog("Logs");
		original.addXp(150L);
		now[0] = now[0].plus(Duration.ofMinutes(6));
		original.addLog("Willow logs");
		original.addXp(50L);

		String json = GSON.toJson(original.toState());
		SessionState state = GSON.fromJson(json, SessionState.class);
		ForestrySession restored = new ForestrySession(state, () -> now[0]);

		assertEquals(4, restored.getLogsCut());
		assertEquals(200L, restored.getXpGained());
		Map<String, Integer> byType = restored.getLogsByType();
		assertEquals(Integer.valueOf(2), byType.get("Oak logs"));
		assertEquals(Integer.valueOf(1), byType.get("Logs"));
		assertEquals(Integer.valueOf(1), byType.get("Willow logs"));

		List<TimeBucket> timeline = restored.getTimeline();
		assertEquals(2, timeline.size());
		assertEquals(3, timeline.get(0).logs);
		assertEquals(150L, timeline.get(0).xp);
		assertEquals(1, timeline.get(1).logs);
		assertEquals(50L, timeline.get(1).xp);
		assertEquals(original.getStart().toEpochMilli(), timeline.get(0).start);
		assertEquals(original.getStart().toEpochMilli() + ForestrySession.BUCKET.toMillis(), timeline.get(1).start);
	}

	@Test
	public void lifetimeStatsRoundTripThroughJson()
	{
		LifetimeStats stats = new LifetimeStats();
		stats.addEvent(ForestryEvent.POACHERS, DAY);
		stats.addEvent(ForestryEvent.POACHERS, DAY);
		stats.addBark(11, ForestryEvent.POACHERS, DAY);
		stats.addBark(3, null, DAY);
		stats.addLeaves(LeafType.YEW, 9, DAY);
		stats.addLog("Oak logs", DAY);
		stats.addLog("Oak logs", DAY);
		stats.addXp(500L, DAY);

		LifetimeStats restored = GSON.fromJson(GSON.toJson(stats), LifetimeStats.class).normalize();
		assertEquals(14, restored.getBark());
		assertEquals(2, restored.getEventsSeen());
		assertEquals(2, restored.getEventCount(ForestryEvent.POACHERS));
		assertEquals(11, restored.getBarkForEvent(ForestryEvent.POACHERS));
		assertEquals(9, restored.getLeaves(LeafType.YEW));
		assertEquals(9, restored.getTotalLeaves());
		assertEquals(2, restored.getLogs());
		assertEquals(Integer.valueOf(2), restored.getLogsByType().get("Oak logs"));
		assertEquals(500L, restored.getXp());

		Map<String, DayStats> days = restored.getDays();
		assertEquals(1, days.size());
		DayStats day = days.get(DAY);
		assertEquals(2, day.events);
		assertEquals(14, day.bark);
		assertEquals(9, day.leaves);
		assertEquals(2, day.logs);
		assertEquals(500L, day.xp);
	}

	@Test
	public void lifetimeStatsAccumulateAcrossMultipleDays()
	{
		LifetimeStats stats = new LifetimeStats();
		stats.addLog("Logs", "2026-09-15");
		stats.addLog("Logs", "2026-09-16");
		stats.addLog("Logs", "2026-09-16");
		stats.addXp(10L, "2026-09-15");
		stats.addXp(20L, "2026-09-16");

		assertEquals(3, stats.getLogs());
		assertEquals(30L, stats.getXp());

		Map<String, DayStats> days = stats.getDays();
		assertEquals(2, days.size());
		// Oldest day first.
		assertEquals("2026-09-15", days.keySet().iterator().next());
		assertEquals(1, days.get("2026-09-15").logs);
		assertEquals(2, days.get("2026-09-16").logs);
		assertEquals(10L, days.get("2026-09-15").xp);
		assertEquals(20L, days.get("2026-09-16").xp);
	}

	@Test
	public void emptyLifetimeJsonIsSafe()
	{
		LifetimeStats restored = GSON.fromJson("{}", LifetimeStats.class).normalize();
		assertEquals(0, restored.getBark());
		assertEquals(0, restored.getEventCount(ForestryEvent.LEPRECHAUN));
		assertEquals(0, restored.getLogs());
		assertEquals(0L, restored.getXp());
		assertTrue(restored.getDays().isEmpty());
	}
}

