	@Inject
	private ScheduledExecutorService executor;

	/** Live NPCs / GameObjects per event; an event is over when its set stays empty for a tick. */
	private final Map<ForestryEvent, Set<Object>> liveEntities = new EnumMap<>(ForestryEvent.class);
	private final Set<ForestryEvent> pendingEnd = EnumSet.noneOf(ForestryEvent.class);

	@Override
	protected void startUp()
	{
		for (ForestryEvent event : ForestryEvent.values())
		{
			liveEntities.put(event, Collections.newSetFromMap(new IdentityHashMap<>()));
		}

		overlayManager.add(overlay);

		panel = new ForestryTrackerPanel(this);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Forestry Tracker")
			.icon(icon)
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		panelTimer = new Timer(PANEL_REFRESH_MS, e -> panel.refresh());
		panelTimer.start();

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			loadPersisted();
		}
	}

	@Override
	protected void shutDown()
	{
		savePersisted();

		overlayManager.remove(overlay);
		if (panelTimer != null)
		{
			panelTimer.stop();
			panelTimer = null;
		}
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;

		session = null;
		lifetime = new LifetimeStats();
		clearLiveEntities();
		lastWcXp = -1;
		dirty = false;
	}

	@Provides
	ForestryTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ForestryTrackerConfig.class);
	}

	public int getLifetimeBark()
	{
		return lifetime.getBark();
	}

	public void resetSession()
	{
		session = null;
		clearLiveEntities();
		savePersisted();
		refreshPanel();
	}

	public void resetLifetime()
	{
		lifetime = new LifetimeStats();
		savePersisted();
		refreshPanel();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ForestryTrackerConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (ForestryTrackerConfig.RESET_LIFETIME_KEY.equals(event.getKey()) && config.resetLifetimeBark())
		{
			resetLifetime();
			configManager.setConfiguration(ForestryTrackerConfig.GROUP, ForestryTrackerConfig.RESET_LIFETIME_KEY, false);
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// Fired once the logged-in character is known; this is when per-character config becomes readable.
		loadPersisted();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
			case HOPPING:
				savePersisted();
				// The next StatChanged after login is only a baseline, not a gain.
				lastWcXp = -1;
				chatState.reset();
				// fallthrough
			case LOADING:
				// Entities are re-spawned after a scene load; if the current event's entities don't come back
				// within a tick it is over.
				if (session != null && session.getCurrentEvent() != null)
				{
					pendingEnd.add(session.getCurrentEvent());
				}
				for (Set<Object> set : liveEntities.values())
				{
					set.clear();
				}
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (handleChatMessage(event.getType(), event.getMessage(), this::activeSession, liveEntities, lifetime, today(), chatState))
		{
			markDirty();
			refreshPanel();
		}
	}

	/**
	 * The chat-parsing/session-update glue behind {@link #onChatMessage(ChatMessage)}, extracted so
	 * it can be unit tested without a full RuneLite {@code Client}/Guice context: only pure
	 * collaborators ({@link ForestrySession}, {@link LifetimeStats}, a plain live-entities map) are
	 * needed. {@code sessionSupplier} is only invoked once a message actually needs a session (bark,
	 * leaves, or a log), matching {@link #activeSession()}'s original call sites so an unrelated chat
	 * line never creates or touches a session.
	 *
	 * @return true if session or lifetime state changed and the caller should persist/refresh
	 */
	static boolean handleChatMessage(ChatMessageType type, String message, Supplier<ForestrySession> sessionSupplier,
		Map<ForestryEvent, Set<Object>> liveEntities, LifetimeStats lifetime, String today, ChatState state)
	{
		if (type != ChatMessageType.SPAM && type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.MESBOX)
		{
			return false;
		}

		if (ChatParser.isLeprechaunLuck(message))
		{
			// The award line follows immediately; remember that it belongs to the Leprechaun.
			state.leprechaunLuckPending = true;
			return false;
		}

		int barkAmount = ChatParser.parseBark(message);
		if (barkAmount >= 0)
		{
			boolean luck = state.leprechaunLuckPending;
			state.leprechaunLuckPending = false;

			ForestrySession s = sessionSupplier.get();
			if (s.getCurrentEvent() == null)
			{
				ForestryEvent lastEvent = s.getLastEvent();
				if (luck && s.isLastRecord(ForestryEvent.LEPRECHAUN))
				{
					// Leprechaun's Luck pays out on log cuts, usually after the leprechaun is gone:
					// attach it to the leprechaun's record regardless of live entities.
					s.resumeLastEvent();
					log.debug("Forestry event resumed: LEPRECHAUN (leprechaun's luck)");
				}
				else if (lastEvent != null && !liveEntities.get(lastEvent).isEmpty() && s.isLastRecord(lastEvent))
				{
					// The player may have stopped participating (rule 1 below) but the event's entities
					// (and thus the event itself, from the player's point of view) are still around;
					// reopen it so this bark attaches to it instead of creating an "Unknown event" or
					// relying on the 10-second grace window.
					s.resumeLastEvent();
					log.debug("Forestry event resumed: {}", lastEvent);
				}
			}
			s.addBark(barkAmount);
			lifetime.addBark(barkAmount, s.getCurrentEvent() != null ? s.getCurrentEvent() : s.getLastEvent(), today);
			log.debug("Bark awarded: {} (event {}, session total {})", barkAmount, s.getLastEvent(), s.getTotalBark());

			if (s.getCurrentEvent() == ForestryEvent.LEPRECHAUN && liveEntities.get(ForestryEvent.LEPRECHAUN).isEmpty())
			{
				// The leprechaun itself has left; close the record again so the luck payout doesn't keep
				// the event "in progress" until the next event starts.
				s.endEvent();
				log.debug("Forestry event ended: LEPRECHAUN (luck payout after despawn)");
			}
			return true;
		}

		if (type != ChatMessageType.SPAM && type != ChatMessageType.GAMEMESSAGE)
		{
			return false;
		}

		LeafType leafType = ChatParser.parseLeaves(message);
		if (leafType != null)
		{
			sessionSupplier.get().addLeaves(leafType, 1);
			lifetime.addLeaves(leafType, 1, today);
			log.debug("Leaf collected: {}", leafType);
			return true;
		}

		String logType = ChatParser.parseLog(message);
		if (logType != null)
		{
			ForestrySession s = sessionSupplier.get();
			ForestryEvent current = s.getCurrentEvent();
			if (current != null && current != ForestryEvent.LEPRECHAUN && s.getCurrentEventBark() > 0)
			{
				// The player went back to chopping after collecting bark from this event: end their
				// participation now rather than waiting for the (possibly much later) despawn of its
				// entities. Events with no bark yet (or one the player never engaged with) are left
				// running, and so is the Leprechaun: its bark (Leprechaun's Luck) is earned BY chopping,
				// so a log cut is participation rather than the end of it.
				s.endEvent();
				log.debug("Forestry event ended: {} (player resumed chopping)", current);
			}
			s.addLog(logType);
			lifetime.addLog(logType, today);
			log.debug("Log cut: {}", logType);
			return true;
		}

		return false;
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.WOODCUTTING)
		{
			return;
		}

		long xp = event.getXp();
		if (lastWcXp < 0)
		{
			// First reading after login (or plugin start): establish the baseline only.
			lastWcXp = xp;
			return;
		}

		long delta = xp - lastWcXp;
		lastWcXp = xp;
		if (delta > 0)
		{
			activeSession().addXp(delta);
			lifetime.addXp(delta, today());
			markDirty();
			refreshPanel();
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		ForestryEvent forestryEvent = ForestryEvent.fromNpcId(event.getNpc().getId());
		if (forestryEvent != null)
		{
			entitySpawned(forestryEvent, event.getNpc());
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		ForestryEvent forestryEvent = ForestryEvent.fromNpcId(event.getNpc().getId());
		if (forestryEvent != null)
		{
			entityDespawned(forestryEvent, event.getNpc());
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		ForestryEvent forestryEvent = ForestryEvent.fromObjectId(event.getGameObject().getId());
		if (forestryEvent != null)
		{
			entitySpawned(forestryEvent, event.getGameObject());
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		ForestryEvent forestryEvent = ForestryEvent.fromObjectId(event.getGameObject().getId());
		if (forestryEvent != null)
		{
			entityDespawned(forestryEvent, event.getGameObject());
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		// Events whose entities all despawned last tick and did not come back are over.
		if (!pendingEnd.isEmpty())
		{
			for (ForestryEvent event : pendingEnd)
			{
				if (liveEntities.get(event).isEmpty() && session != null && session.getCurrentEvent() == event)
				{
					session.endEvent();
					log.debug("Forestry event ended: {}", event);
					markDirty();
					refreshPanel();
				}
			}
			pendingEnd.clear();
		}

		// Inactivity timeout.
		if (session != null && session.isActive())
		{
			Duration timeout = Duration.ofMinutes(config.statTimeout());
			if (session.getCurrentEvent() == null && session.getTimeSinceActivity().compareTo(timeout) >= 0)
			{
				session.setActive(false);
				markDirty();
				refreshPanel();
			}
		}

		// Coalesce persistence: at most one profile-config write per tick, regardless of how many
		// of the handlers above fired this tick.
		if (dirty)
		{
			savePersisted();
			flushWanted = true;
		}

		// RuneLite only writes profile config to disk on a clean shutdown and on a ~5 minute timer, so
		// a crash or force-close would lose everything since then. Ask for a flush (off the client
		// thread) shortly after changes, at most once per FLUSH_INTERVAL.
		if (flushWanted && Duration.between(lastFlush, Instant.now()).compareTo(FLUSH_INTERVAL) >= 0)
		{
			flushWanted = false;
			lastFlush = Instant.now();
			executor.execute(configManager::sendConfig);
		}
	}

	private void entitySpawned(ForestryEvent event, Object entity)
	{
		Set<Object> set = liveEntities.get(event);
		boolean wasEmpty = set.isEmpty();
		set.add(entity);
		pendingEnd.remove(event);

		if (!wasEmpty)
		{
			// Another entity of an event that's already ongoing (e.g. a new glowing root while
			// others are still up). This is not a new occurrence, even if rule 1 already ended the
			// player's participation in it (leaving currentEvent null while the set stays non-empty):
			// only the transition from no live entities to one starts a new event.
			return;
		}

		ForestrySession s = activeSession();
		if (s.getCurrentEvent() != event)
		{
			if (startOrResumeEvent(s, event))
			{
				lifetime.addEvent(event, today());
				log.debug("Forestry event started: {}", event);
			}
			else
			{
				log.debug("Forestry event resumed: {}", event);
			}
			markDirty();
			refreshPanel();
		}
	}

	/**
	 * Decides whether a newly-live entity for {@code event} (the transition from no live entities to
	 * one, per {@link #entitySpawned(ForestryEvent, Object)}) is a genuinely new occurrence or the
	 * continuation of one whose participation had already ended - by the log-cut rule in {@link
	 * #handleChatMessage}, or a despawn/respawn that happened to straddle a tick boundary rather than
	 * landing within the same tick (only the latter is covered by the {@code pendingEnd} add/remove
	 * dance in {@link #entitySpawned}/{@link #entityDespawned}). Mirrors the {@code
	 * resumeLastEvent()}/{@code isLastRecord()} check {@link #handleChatMessage} already does for
	 * bark awards, so an entity-spawn reopen merges back into the same history record instead of
	 * bumping {@code eventsSeen} and splitting the occurrence across two records.
	 *
	 * <p>Extracted (package-private, static) so this decision is unit testable directly against a
	 * {@link ForestrySession} without a RuneLite {@code Client}/Guice context.
	 *
	 * @return true if a new event was started; false if the last completed record was reopened instead
	 */
	static boolean startOrResumeEvent(ForestrySession s, ForestryEvent event)
	{
		if (s.getCurrentEvent() == null && event.equals(s.getLastEvent()) && s.isLastRecord(event))
		{
			s.resumeLastEvent();
			return false;
		}

		s.startEvent(event);
		return true;
	}

	private void entityDespawned(ForestryEvent event, Object entity)
	{
		Set<Object> set = liveEntities.get(event);
		if (set.remove(entity) && set.isEmpty())
		{
			// Defer: state changes (e.g. sapling -> withering sapling) despawn and respawn within the same tick.
			pendingEnd.add(event);
		}
	}

	/** Returns the current session, creating (or replacing a timed-out) one as configured. */
	private ForestrySession activeSession()
	{
		if (session == null || (!session.isActive() && config.resetOnTimeout()))
		{
			session = new ForestrySession();
			pendingEnd.clear();
		}
		else if (!session.isActive())
		{
			session.touch();
		}
		return session;
	}

	private void markDirty()
	{
		dirty = true;
	}

	private static String today()
	{
		return LocalDate.now().toString();
	}

	private void clearLiveEntities()
	{
		for (Set<Object> set : liveEntities.values())
		{
			set.clear();
		}
		pendingEnd.clear();
	}

	// --- persistence -------------------------------------------------------------------------------------------

	private boolean hasProfile()
	{
		return configManager.getRSProfileKey() != null;
	}

	private void loadPersisted()
	{
		if (!hasProfile())
		{
			return;
		}

		LifetimeStats loaded = null;
		String lifetimeJson = configManager.getRSProfileConfiguration(ForestryTrackerConfig.GROUP, LIFETIME_KEY);
		if (lifetimeJson != null)
		{
			try
			{
				loaded = gson.fromJson(lifetimeJson, LifetimeStats.class);
			}
			catch (JsonSyntaxException e)
			{
				log.warn("Discarding unreadable lifetime stats", e);
			}
		}
		if (loaded == null)
		{
			loaded = new LifetimeStats();
			// Migrate the 1.0.0 bark-only total.
			Integer legacy = configManager.getRSProfileConfiguration(ForestryTrackerConfig.GROUP, LEGACY_LIFETIME_BARK_KEY, Integer.class);
			if (legacy != null && legacy > 0)
			{
				loaded.addBark(legacy, null, null);
				configManager.unsetRSProfileConfiguration(ForestryTrackerConfig.GROUP, LEGACY_LIFETIME_BARK_KEY);
			}
		}
		lifetime = loaded.normalize();

		ForestrySession restored = null;
		String sessionJson = configManager.getRSProfileConfiguration(ForestryTrackerConfig.GROUP, SESSION_KEY);
		if (sessionJson != null)
		{
			try
			{
				SessionState state = gson.fromJson(sessionJson, SessionState.class);
				if (state != null)
				{
					restored = new ForestrySession(state);
				}
			}
			catch (RuntimeException e)
			{
				log.warn("Discarding unreadable session", e);
			}
		}
		if (restored != null && restored.isActive())
		{
			// A session persisted as active is never re-touched while the client is closed, so a
			// stale lastActivity here means it actually timed out (e.g. the player logged out, or
			// the client crashed, mid-session) and must not silently resume with a days-old start.
			Duration timeout = Duration.ofMinutes(config.statTimeout());
			if (Duration.between(restored.getLastActivity(), Instant.now()).compareTo(timeout) >= 0)
			{
				restored.setActive(false);
			}
		}
		session = restored;
		clearLiveEntities();

		log.debug("Loaded forestry stats: lifetime bark {}, session {}", lifetime.getBark(),
			session == null ? "none" : session.getTotalBark() + " bark");
		refreshPanel();
	}

	private void savePersisted()
	{
		if (!hasProfile())
		{
			return;
		}
		configManager.setRSProfileConfiguration(ForestryTrackerConfig.GROUP, LIFETIME_KEY, gson.toJson(lifetime));
		if (session == null)
		{
			configManager.unsetRSProfileConfiguration(ForestryTrackerConfig.GROUP, SESSION_KEY);
		}
		else
		{
			configManager.setRSProfileConfiguration(ForestryTrackerConfig.GROUP, SESSION_KEY, gson.toJson(session.toState()));
		}
		dirty = false;
	}

	private void refreshPanel()
	{
		ForestryTrackerPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::refresh);
		}
	}
}

package com.forestrytracker;

/**
 * Lifetime activity for one calendar day (local time). Plain fields so Gson can persist it.
 */
class DayStats
{
	int logs;
	int bark;
	int leaves;
	int events;
	long xp;
}

package com.forestrytracker;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Supplier;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.Setter;

/**
 * Mutable per-session statistics. Pure model: no RuneLite client dependencies so it can be unit tested.
 */
public class ForestrySession
{
	private static final int MAX_HISTORY = 100;

	/**
	 * Cap on the number of timeline slices kept, oldest dropped first. Bounds memory/JSON size
	 * for a session whose {@code start} is very old (e.g. a stale multi-day session touched back
	 * to life) instead of backfilling one slice per {@link #BUCKET} all the way from start.
	 */
	private static final int MAX_TIMELINE = 288;

	/** Width of one timeline slice. */
	static final Duration BUCKET = Duration.ofMinutes(5);

	/**
	 * A bark award arriving this soon after an event ended is attributed to that event
	 * (e.g. the Struggling Sapling reward message can arrive after the sapling despawns).
	 */
	static final Duration BARK_ATTRIBUTION_GRACE = Duration.ofSeconds(10);

	private final Supplier<Instant> clock;

	@Getter
	private final Instant start;
	@Getter
	private Instant lastActivity;
	@Getter
	@Setter
	private boolean active = true;

	@Getter
	private int totalBark;
	@Getter
	private int lastEventBark;
	@Getter
	@Nullable
	private ForestryEvent lastEvent;
	@Getter
	@Nullable
	private Instant lastEventStart;
	@Getter
	@Nullable
	private Instant lastEventEnd;
	@Getter
	@Nullable
	private Instant lastBarkAward;
	@Getter
	private int eventsSeen;
	@Getter
	private int logsCut;
	@Getter
	private long xpGained;

	/**
	 * Total idle time excluded from {@link #getDuration()}: accumulated whenever {@link #touch()}
	 * reactivates a session that had timed out, so a long-idle-then-resumed session doesn't have
	 * that idle gap flood back into per-hour rates.
	 */
	private long pausedMillis;

	private final Map<ForestryEvent, Integer> eventCounts = new EnumMap<>(ForestryEvent.class);
	private final Map<ForestryEvent, Integer> barkByEvent = new EnumMap<>(ForestryEvent.class);
	private final Map<LeafType, Integer> leaves = new EnumMap<>(LeafType.class);
	private final Map<String, Integer> logsByType = new LinkedHashMap<>();
	private final List<EventRecord> history = new ArrayList<>();
	private final List<TimeBucket> timeline = new ArrayList<>();

	@Getter
	@Nullable
	private ForestryEvent currentEvent;
	@Getter
	private int currentEventBark;
	@Getter
	@Nullable
	private Instant currentEventStart;

	public ForestrySession()
	{
		this(Instant::now);
	}

	ForestrySession(Supplier<Instant> clock)
	{
		this.clock = clock;
		this.start = clock.get();
		this.lastActivity = start;
	}

	ForestrySession(SessionState state)
	{
		this(state, Instant::now);
	}

	/** Restores a session from a persisted snapshot. Any event that was in progress is treated as ended. */
	ForestrySession(SessionState state, Supplier<Instant> clock)
	{
		this.clock = clock;
		this.start = Instant.ofEpochMilli(state.start);
		this.lastActivity = Instant.ofEpochMilli(state.lastActivity);
		this.active = state.active;
		this.totalBark = state.totalBark;
		this.lastEventBark = state.lastEventBark;
		this.lastEvent = state.lastEvent;
		this.lastEventStart = toInstant(state.lastEventStart);
		this.lastEventEnd = toInstant(state.lastEventEnd);
		this.lastBarkAward = toInstant(state.lastBarkAward);
		this.eventsSeen = state.eventsSeen;
		this.logsCut = state.logsCut;
		this.xpGained = state.xpGained;
		this.pausedMillis = state.pausedMillis;
		if (state.eventCounts != null)
		{
			state.eventCounts.forEach((k, v) -> putIfPresent(eventCounts, k, v));
		}
		if (state.barkByEvent != null)
		{
			state.barkByEvent.forEach((k, v) -> putIfPresent(barkByEvent, k, v));
		}
		if (state.leaves != null)
		{
			state.leaves.forEach((k, v) -> putIfPresent(leaves, k, v));
		}
		if (state.logsByType != null)
		{
			state.logsByType.forEach((k, v) -> putIfPresent(logsByType, k, v));
		}
		if (state.history != null)
		{
			for (SessionState.RecordState r : state.history)
			{
				if (r == null)
				{
					continue;
				}
				history.add(new EventRecord(r.event, Instant.ofEpochMilli(r.start), toInstant(r.end), r.bark));
				if (history.size() >= MAX_HISTORY)
				{
					break;
				}
			}
		}
		if (state.timeline != null)
		{
			for (TimeBucket b : state.timeline)
			{
				if (b != null)
				{
					timeline.add(b);
				}
			}
			while (timeline.size() > MAX_TIMELINE)
			{
				timeline.remove(0);
			}
		}
	}

	/** Snapshot for persistence. An event in progress is recorded as if it had just ended. */
	SessionState toState()
	{
		SessionState state = new SessionState();
		state.start = start.toEpochMilli();
		state.lastActivity = lastActivity.toEpochMilli();
		state.active = active;
		state.totalBark = totalBark;
		state.lastEventBark = currentEvent != null ? currentEventBark : lastEventBark;
		state.lastEvent = lastEvent;
		state.lastEventStart = toMillis(lastEventStart);
		state.lastEventEnd = toMillis(lastEventEnd);
		state.lastBarkAward = toMillis(lastBarkAward);
		state.eventsSeen = eventsSeen;
		state.logsCut = logsCut;
		state.xpGained = xpGained;
		state.pausedMillis = pausedMillis;
		state.eventCounts.putAll(eventCounts);
		state.barkByEvent.putAll(barkByEvent);
		state.leaves.putAll(leaves);
		state.logsByType.putAll(logsByType);
		state.timeline.addAll(timeline);

		if (currentEvent != null)
		{
			SessionState.RecordState r = new SessionState.RecordState();
			r.event = currentEvent;
			r.start = currentEventStart.toEpochMilli();
			r.end = clock.get().toEpochMilli();
			r.bark = currentEventBark;
			state.history.add(r);
		}
		for (EventRecord record : history)
		{
			SessionState.RecordState r = new SessionState.RecordState();
			r.event = record.getEvent();
			r.start = record.getStart().toEpochMilli();
			r.end = toMillis(record.getEnd());
			r.bark = record.getBark();
			state.history.add(r);
		}
		return state;
	}

	// --- mutation ----------------------------------------------------------------------------------------------

	/**
	 * Marks the session as active right now. Reactivating a session that had timed out excludes
	 * the idle gap since it went inactive from {@link #getDuration()}, so resuming after a long
	 * pause doesn't flood that idle time back into per-hour rates.
	 */
	public void touch()
	{
		Instant now = clock.get();
		if (!active)
		{
			Duration idle = Duration.between(lastActivity, now);
			if (!idle.isNegative())
			{
				pausedMillis += idle.toMillis();
			}
		}
		lastActivity = now;
		active = true;
	}

	/** Called when a Forestry event is first seen. Ends any event still marked current. */
	public void startEvent(ForestryEvent event)
	{
		if (currentEvent != null)
		{
			endEvent();
		}

		Instant now = clock.get();
		currentEvent = event;
		currentEventBark = 0;
		currentEventStart = now;
		lastEvent = event;
		lastEventStart = now;
		eventsSeen++;
		eventCounts.merge(event, 1, Integer::sum);
		bucket().events++;
		touch();
	}

	/**
	 * Re-opens the most recently completed event so it becomes current again, e.g. when the
	 * plugin ended it early (the player stopped participating) but the entities are still around
	 * and later bark should attach to the same event rather than double-counting it. Does not
	 * touch {@link #eventsSeen} or the per-event counts: it is the same event, not a new one.
	 * {@link #lastEventEnd} is cleared since the event is active again, not ended.
	 *
	 * @return true if a record was reopened; false if there is no history, or the most recent
	 * record is a standalone "Unknown event" bark award (nothing to reopen).
	 */
	public boolean resumeLastEvent()
	{
		if (currentEvent != null || history.isEmpty())
		{
			return false;
		}

		EventRecord record = history.get(0);
		if (record.getEvent() == null)
		{
			return false;
		}

		history.remove(0);
		currentEvent = record.getEvent();
		currentEventStart = record.getStart();
		currentEventBark = record.getBark();
		lastEvent = record.getEvent();
		lastEventStart = record.getStart();
		lastEventEnd = null;
		touch();
		return true;
	}

	/**
	 * Whether {@code event} is the event of the most recent history record, i.e. the record
	 * {@link #resumeLastEvent()} would reopen. Lets the plugin decide whether entities it still
	 * sees for {@code event} belong to that record before deciding to reopen it.
	 */
	public boolean isLastRecord(@Nullable ForestryEvent event)
	{
		return !history.isEmpty() && history.get(0).getEvent() == event;
	}

	/** Called when the current event's NPCs/objects are all gone. */
	public void endEvent()
	{
		if (currentEvent == null)
		{
			return;
		}

		Instant now = clock.get();
		lastEventEnd = now;
		lastEventBark = currentEventBark;
		lastEvent = currentEvent;
		addHistory(new EventRecord(currentEvent, currentEventStart, now, currentEventBark));

		currentEvent = null;
		currentEventBark = 0;
		currentEventStart = null;
	}

	/** Records an anima-infused bark award. */
	public void addBark(int amount)
	{
		Instant now = clock.get();
		totalBark += amount;
		lastBarkAward = now;
		bucket().bark += amount;
		touch();

		if (currentEvent != null)
		{
			currentEventBark += amount;
			lastEventBark = currentEventBark;
			barkByEvent.merge(currentEvent, amount, Integer::sum);
			return;
		}

		// Event just ended: attribute to it.
		if (lastEventEnd != null && !history.isEmpty()
			&& Duration.between(lastEventEnd, now).compareTo(BARK_ATTRIBUTION_GRACE) <= 0)
		{
			EventRecord last = history.get(0);
			last.addBark(amount, now);
			lastEventBark = last.getBark();
			if (last.getEvent() != null)
			{
				barkByEvent.merge(last.getEvent(), amount, Integer::sum);
			}
			return;
		}

		// No detected event: record it standalone.
		lastEvent = null;
		lastEventBark = amount;
		lastEventStart = now;
		lastEventEnd = now;
		addHistory(new EventRecord(null, now, now, amount));
	}

	public void addLeaves(LeafType type, int amount)
	{
		if (amount <= 0)
		{
			return;
		}
		leaves.merge(type, amount, Integer::sum);
		bucket().leaves += amount;
		touch();
	}

	/** Records one log (or mushroom) cut; {@code type} is the display name, e.g. "Oak logs". */
	public void addLog(String type)
	{
		logsCut++;
		logsByType.merge(type, 1, Integer::sum);
		bucket().logs++;
		touch();
	}

	/** Records Woodcutting experience gained. */
	public void addXp(long delta)
	{
		if (delta <= 0)
		{
			return;
		}
		xpGained += delta;
		bucket().xp += delta;
		touch();
	}

	// --- queries -----------------------------------------------------------------------------------------------

	public int getLeaves(LeafType type)
	{
		return leaves.getOrDefault(type, 0);
	}

	public int getTotalLeaves()
	{
		int total = 0;
		for (int n : leaves.values())
		{
			total += n;
		}
		return total;
	}

	public int getEventCount(ForestryEvent event)
	{
		return eventCounts.getOrDefault(event, 0);
	}

	public int getBarkForEvent(ForestryEvent event)
	{
		return barkByEvent.getOrDefault(event, 0);
	}

	public Map<String, Integer> getLogsByType()
	{
		return Collections.unmodifiableMap(logsByType);
	}

	/** Newest first. */
	public List<EventRecord> getHistory()
	{
		return Collections.unmodifiableList(history);
	}

	/** Oldest first; one entry per {@link #BUCKET} from the session start up to the last activity. */
	public List<TimeBucket> getTimeline()
	{
		return Collections.unmodifiableList(timeline);
	}

	/** Elapsed session time: up to now while active, frozen at the last activity once timed out. */
	public Duration getDuration()
	{
		Instant end = active ? clock.get() : lastActivity;
		Duration d = Duration.between(start, end).minus(Duration.ofMillis(pausedMillis));
		return d.isNegative() ? Duration.ZERO : d;
	}

	public int getBarkPerHour()
	{
		return (int) perHour(totalBark);
	}

	public int getLogsPerHour()
	{
		return (int) perHour(logsCut);
	}

	public long getXpPerHour()
	{
		return perHour(xpGained);
	}

	public int getLeavesPerHour()
	{
		return (int) perHour(getTotalLeaves());
	}

	/** Events per hour, with one decimal of precision (e.g. 4.5). */
	public double getEventsPerHour()
	{
		long ms = getDuration().toMillis();
		if (eventsSeen == 0 || ms <= 0)
		{
			return 0;
		}
		return Math.round(eventsSeen * 36_000_000.0 / ms) / 10.0;
	}

	public int getAverageBarkPerEvent()
	{
		return eventsSeen == 0 ? 0 : Math.round((float) totalBark / eventsSeen);
	}

	/** The completed event that awarded the most bark, or null. */
	@Nullable
	public EventRecord getBestEvent()
	{
		EventRecord best = null;
		for (EventRecord r : history)
		{
			if (r.getEvent() != null && (best == null || r.getBark() > best.getBark()))
			{
				best = r;
			}
		}
		return best;
	}

	/** Mean time between consecutive event starts, or null with fewer than two events. */
	@Nullable
	public Duration getAverageEventGap()
	{
		List<Instant> starts = new ArrayList<>();
		if (currentEventStart != null)
		{
			starts.add(currentEventStart);
		}
		for (EventRecord r : history)
		{
			if (r.getEvent() != null)
			{
				starts.add(r.getStart());
			}
		}
		if (starts.size() < 2)
		{
			return null;
		}
		Collections.sort(starts);
		long total = Duration.between(starts.get(0), starts.get(starts.size() - 1)).toMillis();
		return Duration.ofMillis(total / (starts.size() - 1));
	}

	/** Time since the most recent event began (or, failing that, the most recent bark award). */
	@Nullable
	public Duration getTimeSinceLastEvent()
	{
		Instant ref = lastEventStart != null ? lastEventStart : lastBarkAward;
		if (ref == null)
		{
			return null;
		}
		return Duration.between(ref, clock.get());
	}

	public Duration getTimeSinceActivity()
	{
		return Duration.between(lastActivity, clock.get());
	}

	// --- internals ---------------------------------------------------------------------------------------------

	private long perHour(long count)
	{
		if (count <= 0)
		{
			return 0;
		}
		long ms = getDuration().toMillis();
		if (ms <= 0)
		{
			return 0;
		}
		return (long) ((double) count * Duration.ofHours(1).toMillis() / ms);
	}

	/**
	 * The timeline slice containing "now", creating empty slices up to it as needed. Drops the
	 * oldest slices first so a session whose activity resumes long after {@code start} (e.g. a
	 * stale multi-day session restored from disk) can't grow this list without bound.
	 */
	private TimeBucket bucket()
	{
		long bucketMs = BUCKET.toMillis();
		long idx = Math.max(0, Duration.between(start, clock.get()).toMillis() / bucketMs);

		while (!timeline.isEmpty() && idx - firstBucketIndex(bucketMs) >= MAX_TIMELINE)
		{
			timeline.remove(0);
		}

		long base = timeline.isEmpty() ? Math.max(0, idx - MAX_TIMELINE + 1) : firstBucketIndex(bucketMs);
		while (timeline.size() <= idx - base)
		{
			timeline.add(new TimeBucket(start.toEpochMilli() + (base + timeline.size()) * bucketMs));
		}
		return timeline.get((int) (idx - base));
	}

	/** Absolute (from {@code start}) bucket index of the oldest slice currently kept. */
	private long firstBucketIndex(long bucketMs)
	{
		return (timeline.get(0).start - start.toEpochMilli()) / bucketMs;
	}

	private void addHistory(EventRecord record)
	{
		history.add(0, record);
		while (history.size() > MAX_HISTORY)
		{
			history.remove(history.size() - 1);
		}
	}

	private static <K> void putIfPresent(Map<K, Integer> map, K key, Integer value)
	{
		if (key != null && value != null)
		{
			map.put(key, value);
		}
	}

	@Nullable
	private static Instant toInstant(@Nullable Long millis)
	{
		return millis == null ? null : Instant.ofEpochMilli(millis);
	}

	@Nullable
	private static Long toMillis(@Nullable Instant instant)
	{
		return instant == null ? null : instant.toEpochMilli();
	}
}

package com.forestrytracker;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.ItemID;

/**
 * Leaf items that Forestry can award / store in the forestry kit.
 */
@Getter
@RequiredArgsConstructor
public enum LeafType
{
	NORMAL("Leaves", ItemID.LEAVES),
	OAK("Oak leaves", ItemID.LEAVES_OAK),
	WILLOW("Willow leaves", ItemID.LEAVES_WILLOW),
	MAPLE("Maple leaves", ItemID.LEAVES_MAPLE),
	YEW("Yew leaves", ItemID.LEAVES_YEW),
	MAGIC("Magic leaves", ItemID.LEAVES_MAGIC);

	private final String displayName;
	private final int itemId;

	public static LeafType fromItemId(int itemId)
	{
		for (LeafType type : values())
		{
			if (type.itemId == itemId)
			{
				return type;
			}
		}
		return null;
	}
}

package com.forestrytracker;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.IntConsumer;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * A two-way segmented control ("Session" | "Lifetime"): the active tab gets orange text and a 2px
 * orange bottom border, the inactive tab is muted grey.
 */
class TabBar extends JPanel
{
	private static final Color BORDER = new Color(58, 58, 58);

	private final JLabel[] tabs;
	private int selected;

	TabBar(String[] labels, IntConsumer onChange)
	{
		super(new GridLayout(1, labels.length, 0, 0));
		setBorder(BorderFactory.createLineBorder(BORDER));
		setAlignmentX(LEFT_ALIGNMENT);
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);

		tabs = new JLabel[labels.length];
		for (int i = 0; i < labels.length; i++)
		{
			int index = i;
			JLabel tab = new JLabel(labels[i], SwingConstants.CENTER);
			tab.setFont(FontManager.getRunescapeSmallFont());
			tab.setOpaque(true);
			tab.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			tab.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					if (selected != index)
					{
						setSelected(index);
						onChange.accept(index);
					}
				}
			});
			tabs[i] = tab;
			add(tab);
		}
		setSelected(0);
	}

	void setSelected(int index)
	{
		selected = index;
		for (int i = 0; i < tabs.length; i++)
		{
			JLabel tab = tabs[i];
			tab.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			if (i == index)
			{
				tab.setForeground(ColorScheme.BRAND_ORANGE);
				tab.setBorder(new CompoundBorder(
					new MatteBorder(0, 0, 2, 0, ColorScheme.BRAND_ORANGE),
					new EmptyBorder(5, 0, 3, 0)));
			}
			else
			{
				tab.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				tab.setBorder(new EmptyBorder(5, 0, 5, 0));
			}
		}
	}

	int getSelected()
	{
		return selected;
	}
}

package com.forestrytracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.FlowLayout;
