package com.forestrytracker;

import javax.swing.ImageIcon;
import javax.swing.JLabel;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

/**
 * Small helper for loading a game item's sprite into a {@link JLabel}, resized for the side panel.
 */
final class ItemIcons
{
	private ItemIcons()
	{
	}

	/** Asynchronously (or immediately, if already cached) sets {@code label}'s icon to item {@code itemId}. */
	static void apply(ItemManager itemManager, int itemId, JLabel label, int size)
	{
		if (itemManager == null)
		{
			return;
		}
		AsyncBufferedImage img = itemManager.getImage(itemId);
		Runnable set = () -> label.setIcon(new ImageIcon(ImageUtil.resizeImage(img, size, size)));
		img.onLoaded(set);
		set.run();
	}
}

package com.forestrytracker;

/**
 * Small piece of state carried between consecutive chat messages by
 * {@link ForestryTrackerPlugin#handleChatMessage}.
 */
class ChatState
{
	/**
	 * Set by the "You use your leprechaun's luck..." line; consumed by the bark award that follows it,
	 * so that award is attributed to the Leprechaun even though it arrives while chopping and possibly
	 * after the leprechaun has despawned.
	 */
	boolean leprechaunLuckPending;

	void reset()
	{
		leprechaunLuckPending = false;
	}
}

package com.forestrytracker;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Pure chat-message parsing for Forestry-related game messages. No RuneLite client dependency so
 * it can be unit tested directly.
 *
 * <p>In-game chat lines dress plain text up with colour tags (e.g. {@code <col=0000ff>...</col>})
 * and, for some Forestry messages, chatbox macros (e.g. {@code @mes_hl_blu@}). {@link
 * #stripFormatting(String)} normalises a raw message to plain text before any of the {@code
 * parse*} methods look at it.
 */
final class ChatParser
{
	/**
	 * Bark award message. The core Woodcutting plugin matches
	 * "You've been awarded <col=..>N Anima-infused bark</col>."; this is slightly looser about the
	 * apostrophe and casing, and is applied after {@link #stripFormatting(String)} has already
	 * removed any colour tags or macros.
	 */
	private static final Pattern ANIMA_BARK_PATTERN = Pattern.compile(
		"You(?:'|’)?ve been awarded (\\d+) Anima-infused bark\\.?|You have been awarded (\\d+) Anima-infused bark\\.?",
		Pattern.CASE_INSENSITIVE);

	/** Leaves picked up into the forestry kit; the leaf-type word is absent for plain "leaves". */
	private static final Pattern LEAF_PATTERN = Pattern.compile(
		"Some (?:(oak|willow|maple|yew|magic) )?leaves fall to the ground and you place them into your Forestry kit\\.?",
		Pattern.CASE_INSENSITIVE);

	/** Log-cutting message; matches the same text the core Woodcutting plugin keys off. */
	private static final Pattern LOG_CUT_PATTERN = Pattern.compile(
		"You get (?:some|an) ([\\w ]*?(?:logs?|mushrooms))\\.?",
		Pattern.CASE_INSENSITIVE);

	/**
	 * Leprechaun's Luck: after standing in the rainbow, the next several log cuts each pay bark. This
	 * line precedes the normal "You've been awarded ..." award and is the only way to tell that bark
	 * apart from other awards, since it arrives while chopping and often after the leprechaun has left.
	 */
	private static final Pattern LEPRECHAUN_LUCK_PATTERN = Pattern.compile(
		"You use (?:the last of )?your leprechaun(?:'|’)s luck to gather some Anima-infused bark\\.?",
		Pattern.CASE_INSENSITIVE);

	/** Strips HTML-ish colour tags (e.g. {@code <col=0000ff>}, {@code </col>}) from a chat message. */
	private static final Pattern TAG_PATTERN = Pattern.compile("<[^>]*>");

	/** Strips chatbox macros such as {@code @mes_hl_blu@}. */
	private static final Pattern MACRO_PATTERN = Pattern.compile("@[^@]*@");

	private ChatParser()
	{
	}

	/**
	 * Removes every {@code <...>} tag and every {@code @...@} chat macro, collapses doubled spaces
	 * left behind, and trims the result.
	 */
	static String stripFormatting(String msg)
	{
		String stripped = TAG_PATTERN.matcher(msg).replaceAll("");
		stripped = MACRO_PATTERN.matcher(stripped).replaceAll("");
		stripped = stripped.replaceAll(" {2,}", " ");
		return stripped.trim();
	}

	/**
	 * Parses a "You've been awarded N Anima-infused bark." message (after {@link
	 * #stripFormatting(String)}). Returns -1 if {@code msg} isn't a bark award message.
	 */
	static int parseBark(String msg)
	{
		Matcher m = ANIMA_BARK_PATTERN.matcher(stripFormatting(msg));
		if (!m.find())
		{
			return -1;
		}
		String amount = m.group(1) != null ? m.group(1) : m.group(2);
		return Integer.parseInt(amount);
	}

	/** True for the "You use your leprechaun's luck to gather some Anima-infused bark." line. */
	static boolean isLeprechaunLuck(String msg)
	{
		return LEPRECHAUN_LUCK_PATTERN.matcher(stripFormatting(msg)).find();
	}

	/**
	 * Parses a "Some [type ]leaves fall to the ground and you place them into your Forestry kit."
	 * message (after {@link #stripFormatting(String)}) into the {@link LeafType} collected. Returns
	 * null if {@code msg} doesn't match (including leaves that fell but were not collected).
	 */
	static LeafType parseLeaves(String msg)
	{
		Matcher m = LEAF_PATTERN.matcher(stripFormatting(msg));
		if (!m.matches())
		{
			return null;
		}
		String type = m.group(1);
		if (type == null)
		{
			return LeafType.NORMAL;
		}
		switch (type.toLowerCase())
		{
			case "oak":
				return LeafType.OAK;
			case "willow":
				return LeafType.WILLOW;
			case "maple":
				return LeafType.MAPLE;
			case "yew":
				return LeafType.YEW;
			case "magic":
				return LeafType.MAGIC;
			default:
				return null;
		}
	}

	/**
	 * Parses a "You get some/an &lt;type&gt;." log-cutting message (after {@link
	 * #stripFormatting(String)}) into a capitalised type name (e.g. "Willow logs"). Returns null if
	 * {@code msg} doesn't match.
	 */
	static String parseLog(String msg)
	{
		Matcher m = LOG_CUT_PATTERN.matcher(stripFormatting(msg));
		if (!m.find())
		{
			return null;
		}
		return capitalize(m.group(1));
	}

	private static String capitalize(String s)
	{
		if (s == null || s.isEmpty())
		{
			return s;
		}
		return Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.forestrytracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Duration;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

class ForestryTrackerOverlay extends OverlayPanel
{
	private static final Color ACTIVE_EVENT = new Color(120, 220, 120);

	private final ForestryTrackerPlugin plugin;
	private final ForestryTrackerConfig config;

	@Inject
	ForestryTrackerOverlay(ForestryTrackerPlugin plugin, ForestryTrackerConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		addMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, "Forestry Tracker overlay");
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		ForestrySession session = plugin.getSession();
		if (!config.showOverlay() || session == null || !session.isActive())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Forestry")
			.color(session.getCurrentEvent() != null ? ACTIVE_EVENT : Color.WHITE)
			.build());

		if (config.showEventName())
		{
			ForestryEvent current = session.getCurrentEvent();
			ForestryEvent last = session.getLastEvent();
			String name = current != null ? current.getDisplayName()
				: last != null ? last.getDisplayName()
				: session.getLastBarkAward() != null ? "Unknown" : "-";
			panelComponent.getChildren().add(LineComponent.builder()
				.left(current != null ? "Event:" : "Last event:")
				.right(name)
				.rightColor(current != null ? ACTIVE_EVENT : Color.WHITE)
				.build());
		}

		if (config.showTimeSinceEvent())
		{
			Duration since = session.getTimeSinceLastEvent();
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Since event:")
				.right(since == null ? "-" : formatDuration(since))
				.build());
		}

		if (config.showLastEventBark())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Last event bark:")
				.right(Integer.toString(session.getLastEventBark()))
				.build());
		}

		if (config.showBarkPerHour())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Bark/hr:")
				.right(Integer.toString(session.getBarkPerHour()))
				.build());
		}

		if (config.showLogs())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Logs:")
				.right(Integer.toString(session.getLogsCut()))
				.build());
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Logs/hr:")
				.right(formatRate(session.getLogsPerHour()))
				.build());
		}

		if (config.showXp())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("XP/hr:")
				.right(formatRate(session.getXpPerHour()))
				.build());
		}

		if (config.showSessionBark())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Session bark:")
				.right(Integer.toString(session.getTotalBark()))
				.build());
		}

		if (config.showLifetimeBark())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Lifetime bark:")
				.right(Integer.toString(plugin.getLifetimeBark()))
				.build());
		}

		if (config.showEventsSeen())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Events:")
				.right(Integer.toString(session.getEventsSeen()))
				.build());
		}

		if (config.showLeaves())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Leaves:")
				.right(Integer.toString(session.getTotalLeaves()))
				.build());

			if (config.leavesBreakdown())
			{
				for (LeafType type : LeafType.values())
				{
					int n = session.getLeaves(type);
					if (n > 0)
					{
						panelComponent.getChildren().add(LineComponent.builder()
							.left("  " + type.getDisplayName() + ":")
							.right(Integer.toString(n))
							.build());
					}
				}
			}
		}

		return super.render(graphics);
	}

	/** Formats a per-hour rate, abbreviating to e.g. "12.4k" once it reaches 10,000. */
	static String formatRate(long value)
	{
		if (value >= 10_000)
		{
			return String.format("%.1fk", value / 1000.0);
		}
		return Long.toString(value);
	}

	static String formatDuration(Duration d)
	{
		long secs = Math.max(0, d.getSeconds());
		long h = secs / 3600;
		long m = (secs % 3600) / 60;
		long s = secs % 60;
		if (h > 0)
		{
			return String.format("%d:%02d:%02d", h, m, s);
		}
		return String.format("%02d:%02d", m, s);
	}
}

package com.forestrytracker;

import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.TreeMap;
import lombok.Getter;

/**
 * Running totals across all sessions for one character. Serialized as JSON into the RuneScape profile config.
 * Per-day figures are keyed by ISO local date ("2026-09-17") and capped at {@link #MAX_DAYS}.
 */
class LifetimeStats
{
	static final int MAX_DAYS = 90;

	@Getter
	private int bark;
	@Getter
	private int eventsSeen;
	@Getter
	private int logs;
	@Getter
	private long xp;
	private Map<ForestryEvent, Integer> eventCounts = new EnumMap<>(ForestryEvent.class);
	private Map<ForestryEvent, Integer> barkByEvent = new EnumMap<>(ForestryEvent.class);
	private Map<LeafType, Integer> leaves = new EnumMap<>(LeafType.class);
	private Map<String, Integer> logsByType = new LinkedHashMap<>();
	private Map<String, DayStats> days = new TreeMap<>();

	void addBark(int amount, ForestryEvent event, String day)
	{
		bark += amount;
		if (event != null)
		{
			barkByEvent.merge(event, amount, Integer::sum);
		}
		day(day).bark += amount;
	}

	void addEvent(ForestryEvent event, String day)
	{
		eventsSeen++;
		eventCounts.merge(event, 1, Integer::sum);
		day(day).events++;
	}

	void addLeaves(LeafType type, int amount, String day)
	{
		if (amount > 0)
		{
			leaves.merge(type, amount, Integer::sum);
			day(day).leaves += amount;
		}
	}

	void addLog(String type, String day)
	{
		logs++;
		logsByType.merge(type, 1, Integer::sum);
		day(day).logs++;
	}

	void addXp(long delta, String day)
	{
		if (delta > 0)
		{
			xp += delta;
			day(day).xp += delta;
		}
	}

	int getEventCount(ForestryEvent event)
	{
		return eventCounts.getOrDefault(event, 0);
	}

	int getBarkForEvent(ForestryEvent event)
	{
		return barkByEvent.getOrDefault(event, 0);
	}

	int getLeaves(LeafType type)
	{
		return leaves.getOrDefault(type, 0);
	}

	int getTotalLeaves()
	{
		int total = 0;
		for (int n : leaves.values())
		{
			total += n;
		}
		return total;
	}

	Map<String, Integer> getLogsByType()
	{
		return Collections.unmodifiableMap(logsByType);
	}

	/** Oldest day first. */
	Map<String, DayStats> getDays()
	{
		return Collections.unmodifiableMap(days);
	}

	private DayStats day(String key)
	{
		if (key == null)
		{
			return new DayStats();
		}
		DayStats d = days.get(key);
		if (d == null)
		{
			d = new DayStats();
			days.put(key, d);
			while (days.size() > MAX_DAYS)
			{
				days.remove(((TreeMap<String, DayStats>) days).firstKey());
			}
		}
		return d;
	}

	/** Gson may leave maps as plain HashMaps or null; normalise after deserialization. */
	LifetimeStats normalize()
	{
		eventCounts = copy(eventCounts, ForestryEvent.class);
		barkByEvent = copy(barkByEvent, ForestryEvent.class);
		leaves = copy(leaves, LeafType.class);
		logsByType = logsByType == null ? new LinkedHashMap<>() : new LinkedHashMap<>(logsByType);
		Map<String, DayStats> sortedDays = new TreeMap<>();
		if (days != null)
		{
			days.forEach((k, v) ->
			{
				if (k != null && v != null)
				{
					sortedDays.put(k, v);
				}
			});
		}
		days = sortedDays;
		return this;
	}

	private static <K extends Enum<K>> Map<K, Integer> copy(Map<K, Integer> source, Class<K> type)
	{
		Map<K, Integer> result = new EnumMap<>(type);
		if (source != null)
		{
			source.forEach((k, v) ->
			{
				if (k != null && v != null)
				{
					result.put(k, v);
				}
			});
		}
		return result;
	}
}

package com.forestrytracker;

import java.time.Instant;
import javax.annotation.Nullable;
import lombok.AllArgsConstructor;
import lombok.Getter;

/**
 * One completed Forestry event (or a bark award that could not be tied to a detected event).
 */
@Getter
@AllArgsConstructor
public class EventRecord
{
	@Nullable
	private final ForestryEvent event;
	private final Instant start;
	private Instant end;
	private int bark;

	void addBark(int amount, Instant when)
	{
		bark += amount;
		end = when;
	}

	public String getEventName()
	{
		return event == null ? "Unknown event" : event.getDisplayName();
	}
}

package com.forestrytracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.FlowLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * A bordered card with a clickable header (chevron, optional icon, title, right-aligned count)
 * that shows/hides a body panel. The caller populates {@link #getBody()} once and mutates its
 * children across refreshes; this component only manages the expand/collapse chrome.
 */
class CollapsibleSection extends JPanel
{
	private static final Color BORDER = new Color(58, 58, 58);

	private final JLabel chevron = new JLabel();
	private final JLabel icon = new JLabel();
	private final JLabel countLabel = new JLabel();
	private final JPanel body = new JPanel();
	private boolean expanded;

	CollapsibleSection(String title)
	{
		this(title, null, null, true);
	}

	CollapsibleSection(String title, Integer iconItemId, ItemManager itemManager, boolean expandedByDefault)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(new CompoundBorder(new LineBorder(BORDER, 1), new EmptyBorder(6, 7, 6, 7)));
		setAlignmentX(LEFT_ALIGNMENT);

		JPanel header = new JPanel(new BorderLayout(4, 0));
		header.setOpaque(false);
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		header.setAlignmentX(LEFT_ALIGNMENT);

		JPanel left = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		left.setOpaque(false);
		chevron.setFont(FontManager.getRunescapeSmallFont());
		chevron.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		left.add(chevron);
		if (iconItemId != null)
		{
			ItemIcons.apply(itemManager, iconItemId, icon, 16);
			left.add(icon);
		}
		JLabel titleLabel = new JLabel(title);
		titleLabel.setFont(FontManager.getRunescapeBoldFont());
		titleLabel.setForeground(Color.WHITE);
		left.add(titleLabel);
		header.add(left, BorderLayout.WEST);

		countLabel.setFont(FontManager.getRunescapeSmallFont());
		countLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		countLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		header.add(countLabel, BorderLayout.EAST);

		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				setExpanded(!expanded);
			}
		});

		add(header);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setOpaque(false);
		body.setAlignmentX(LEFT_ALIGNMENT);
		body.setBorder(BorderFactory.createEmptyBorder(6, 0, 0, 0));
		add(body);

		setExpanded(expandedByDefault);
	}

	/**
	 * Bounds this card to its own preferred height so it can't be stretched to fill leftover
	 * vertical space in the enclosing {@code BoxLayout(Y_AXIS)} column, unlike every other row
	 * type in the panel which is explicitly bounded. Header/body use {@link BorderLayout}, whose
	 * {@code maximumLayoutSize()} is unbounded, so without this override the card's own maximum
	 * size is unbounded too.
	 */
	@Override
	public java.awt.Dimension getMaximumSize()
	{
		return new java.awt.Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	JPanel getBody()
	{
		return body;
	}

	void setCount(String text)
	{
		countLabel.setText(text);
	}

	boolean isExpanded()
	{
		return expanded;
	}

	void setExpanded(boolean expanded)
	{
		this.expanded = expanded;
		chevron.setText(expanded ? "▾" : "▸");
		body.setVisible(expanded);
		revalidate();
		repaint();
	}
}

package com.forestrytracker;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;

/**
 * The nine Forestry events, with lookups from the NPC and GameObject ids that make them up.
 * Ids mirror those used by RuneLite's core Woodcutting plugin.
 */
@Getter
@RequiredArgsConstructor
public enum ForestryEvent
{
	RISING_ROOTS("Rising Roots"),
	STRUGGLING_SAPLING("Struggling Sapling"),
	FLOWERING_TREE("Flowering Tree"),
	LEPRECHAUN("Leprechaun"),
	POACHERS("Poachers"),
	PHEASANT_CONTROL("Pheasant Control"),
	BEE_HIVE("Bee Hive"),
	ENCHANTMENT_RITUAL("Enchantment Ritual"),
	FRIENDLY_ENT("Friendly Ent");

	private final String displayName;

	/**
	 * @return the event an NPC belongs to, or null if the NPC is not part of a Forestry event
	 */
	public static ForestryEvent fromNpcId(int id)
	{
		switch (id)
		{
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_COL01:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_COL02:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_COL03:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_COL04:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_COL05:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_COL06:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_COL07:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_COL08:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_FRUITED_COL01:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_FRUITED_COL02:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_FRUITED_COL03:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_FRUITED_COL04:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_FRUITED_COL05:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_FRUITED_COL06:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_FRUITED_COL07:
			case NpcID.GATHERING_EVENT_FLOWERING_TREE_BUSH_FRUITED_COL08:
				// Note: GATHERING_EVENT_FLOWERING_TREE_BEES is deliberately NOT mapped. Despite its name the
				// bees NPC also appears during the Bee Hive event, so it would misidentify that event.
				return FLOWERING_TREE;

			case NpcID.GATHERING_EVENT_WOODCUTTING_LEPRECHAUN:
				return LEPRECHAUN;

			case NpcID.GATHERING_EVENT_POACHERS_FOX_OUTDOORS:
			case NpcID.GATHERING_EVENT_POACHERS_FOX_INDOORS:
			case NpcID.GATHERING_EVENT_POACHERS_TRAP:
			case NpcID.GATHERING_EVENT_POACHERS_POACHER01_OUTDOORS:
			case NpcID.GATHERING_EVENT_POACHERS_POACHER02_OUTDOORS:
			case NpcID.GATHERING_EVENT_POACHERS_POACHER03_OUTDOORS:
			case NpcID.GATHERING_EVENT_POACHERS_POACHER01_INDOORS:
			case NpcID.GATHERING_EVENT_POACHERS_POACHER02_INDOORS:
			case NpcID.GATHERING_EVENT_POACHERS_POACHER03_INDOORS:
				return POACHERS;

			case NpcID.GATHERING_EVENT_PHEASANT_FORESTER:
			case NpcID.GATHERING_EVENT_PHEASANT:
				return PHEASANT_CONTROL;

			case NpcID.GATHERING_EVENT_BEES_BEEKEEPER:
			case NpcID.GATHERING_EVENT_BEES_BEEBOX_1:
			case NpcID.GATHERING_EVENT_BEES_BEEBOX_2:
			case NpcID.GATHERING_EVENT_BEES_BEEBOX_3:
			case NpcID.GATHERING_EVENT_BEES_BEEBOX_4:
				return BEE_HIVE;

			case NpcID.GATHERING_EVENT_ENCHANTED_RITUAL_DRYAD:
				return ENCHANTMENT_RITUAL;

			case NpcID.GATHERING_EVENT_ENTLINGS_NPC_01:
			case NpcID.GATHERING_EVENT_ENTLINGS_NPC_01_PRUNED:
				return FRIENDLY_ENT;

			default:
				if (id >= NpcID.GATHERING_EVENT_ENCHANTED_RITUAL_A_1 && id <= NpcID.GATHERING_EVENT_ENCHANTED_RITUAL_D_4)
				{
					return ENCHANTMENT_RITUAL;
				}
				return null;
		}
	}

	/**
	 * @return the event a GameObject belongs to, or null if the object is not part of a Forestry event
	 */
	public static ForestryEvent fromObjectId(int id)
	{
		switch (id)
		{
			case ObjectID.GATHERING_EVENT_RISING_ROOTS:
			case ObjectID.GATHERING_EVENT_RISING_ROOTS_SPECIAL:
				return RISING_ROOTS;

			case ObjectID.GATHERING_EVENT_SAPLING_1X1:
			case ObjectID.GATHERING_EVENT_SAPLING_WITHERING_1X1:
			case ObjectID.GATHERING_EVENT_SAPLING_SAVED_1X1:
			case ObjectID.GATHERING_EVENT_SAPLING_2X2:
			case ObjectID.GATHERING_EVENT_SAPLING_WITHERING_2X2:
			case ObjectID.GATHERING_EVENT_SAPLING_SAVED_2X2:
			case ObjectID.GATHERING_EVENT_SAPLING_3X3:
			case ObjectID.GATHERING_EVENT_SAPLING_WITHERING_3X3:
			case ObjectID.GATHERING_EVENT_SAPLING_SAVED_3X3:
			case ObjectID.GATHERING_EVENT_SAPLING_4X4:
			case ObjectID.GATHERING_EVENT_SAPLING_WITHERING_4X4:
			case ObjectID.GATHERING_EVENT_SAPLING_SAVED_4X4:
			case ObjectID.GATHERING_EVENT_SAPLING_INGREDIENT_1:
			case ObjectID.GATHERING_EVENT_SAPLING_INGREDIENT_2:
			case ObjectID.GATHERING_EVENT_SAPLING_INGREDIENT_3:
			case ObjectID.GATHERING_EVENT_SAPLING_INGREDIENT_4A:
			case ObjectID.GATHERING_EVENT_SAPLING_INGREDIENT_4B:
			case ObjectID.GATHERING_EVENT_SAPLING_INGREDIENT_4C:
			case ObjectID.GATHERING_EVENT_SAPLING_INGREDIENT_5:
				return STRUGGLING_SAPLING;

			case ObjectID.GATHERING_EVENT_WOODCUTTING_LEPRECHAUN_RAINBOW:
			case ObjectID.GATHERING_EVENT_WOODCUTTING_LEPRECHAUN_CLOVER:
				return LEPRECHAUN;

			case ObjectID.GATHERING_EVENT_PHEASANT_NEST01:
			case ObjectID.GATHERING_EVENT_PHEASANT_NEST02:
				return PHEASANT_CONTROL;

			case ObjectID.GATHERING_EVENT_BEES_BEEHIVE01:
				return BEE_HIVE;

			default:
				return null;
		}
	}
}

package com.forestrytracker;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Serializable snapshot of a {@link ForestrySession}; stored as JSON in the RuneScape profile config.
 * Instants are epoch milliseconds; null means "not set".
 */
class SessionState
{
	long start;
	long lastActivity;
	boolean active;
	int totalBark;
	int lastEventBark;
	ForestryEvent lastEvent;
	Long lastEventStart;
	Long lastEventEnd;
	Long lastBarkAward;
	int eventsSeen;
	int logsCut;
	long xpGained;
	long pausedMillis;
	Map<ForestryEvent, Integer> eventCounts = new EnumMap<>(ForestryEvent.class);
	Map<ForestryEvent, Integer> barkByEvent = new EnumMap<>(ForestryEvent.class);
	Map<LeafType, Integer> leaves = new EnumMap<>(LeafType.class);
	Map<String, Integer> logsByType = new LinkedHashMap<>();
	List<RecordState> history = new ArrayList<>();
	List<TimeBucket> timeline = new ArrayList<>();

	static class RecordState
	{
		ForestryEvent event;
		long start;
		Long end;
		int bark;
	}
}
